const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');

const contexts = new WeakSet();
const same = (left, right) => JSON.stringify(left) === JSON.stringify(right);

// Full main/WAL hashes bind a cached SQL check to the bytes SQLite read. SHM is
// an index/lock file, not SQL data. The policy owner's separate three-file copy
// and race guards still hash and compare SHM as well.
function dataHashes(target) {
    return ['', '-wal'].map(suffix => {
        if (!fs.existsSync(target + suffix)) return null;
        const hash = createHash('sha256'), buffer = Buffer.allocUnsafe(1024 * 1024);
        const fd = fs.openSync(target + suffix, 'r');
        try {
            let length;
            while ((length = fs.readSync(fd, buffer, 0, buffer.length, null))) hash.update(buffer.subarray(0, length));
        } finally { fs.closeSync(fd); }
        return hash.digest('hex');
    });
}
function optionalDataHashes(target) {
    // A failed cache binding never creates a new refusal: use the real SQL
    // checks again. The owning installers retain their existing error paths.
    try { return dataHashes(target); } catch { return null; }
}

function createStartupReadinessContext() {
    let original, connection, facade, activePath, closed = false;
    let checks = new Map(), checkedVersion = null, firstReadVersion = null;
    let policy, chart, policyCopyHashes;
    const retainedSnapshots = new Set();

    function releaseReader() {
        if (!connection) return;
        try { if (connection.inTransaction) connection.exec('ROLLBACK'); }
        finally { connection.close(); connection = facade = null; }
    }
    const context = {
        open(Database, target, options) {
            if (closed) throw new TypeError('The startup readiness context is closed.');
            const resolved = path.resolve(target);
            if (!original) original = resolved;
            if (resolved !== original && !retainedSnapshots.has(resolved) && resolved !== activePath)
                throw new TypeError('A startup context belongs to one database and its retained snapshot.');
            if (connection && resolved !== original && resolved !== activePath) {
                releaseReader();
                const version = optionalDataHashes(resolved);
                if (!checkedVersion || !same(checkedVersion, version)) checks = new Map();
                firstReadVersion = version;
                checkedVersion = checks.size ? version : null;
            }
            if (connection) return facade;
            activePath = resolved;
            connection = new Database(resolved, options);
            connection.exec('BEGIN');
            const reader = connection;
            facade = new Proxy(reader, {
                get(db, key) {
                    // Existing installer finally blocks release their lease;
                    // the startup owner closes the one private read transaction.
                    if (key === 'close') return () => {};
                    if (key === 'pragma') return (sql, pragmaOptions) => {
                        const name = sql.trim().toLowerCase();
                        // This private facade accepts only the two startup
                        // checks. SQL stays literal and visible to the scanner.
                        if (name !== 'integrity_check' && name !== 'foreign_key_check')
                            throw new TypeError('The startup context supports only integrity and foreign-key checks.');
                        if (!checks.has(name)) checks.set(name, name === 'integrity_check'
                            ? db.pragma('integrity_check') : db.pragma('foreign_key_check'));
                        // Preserve the owners' full-row and simple result views.
                        if (name === 'foreign_key_check' && !checkedVersion) {
                            const after = optionalDataHashes(activePath);
                            if (firstReadVersion && same(firstReadVersion, after)) checkedVersion = after;
                        }
                        const rows = checks.get(name);
                        return structuredClone(pragmaOptions?.simple ? (rows.length ? Object.values(rows[0])[0] : undefined) : rows);
                    };
                    if (key === 'prepare' && !firstReadVersion)
                        firstReadVersion = optionalDataHashes(activePath);
                    // Prepared statements use the ordinary bound method. Their
                    // SQL remains visible at each owning installer call site.
                    const value = Reflect.get(db, key, db);
                    return typeof value === 'function' ? value.bind(db) : value;
                }
            });
            return facade;
        },
        beforeSnapshot() {
            releaseReader();
        },
        useSnapshot(copy, originalHashes) {
            const version = ['', '-wal'].map(suffix => originalHashes[suffix]);
            if (!checkedVersion || !same(checkedVersion, version)) checks = new Map();
            activePath = copy;
            firstReadVersion = version;
            checkedVersion = checks.size ? version : null;
        },
        reviewPolicy(target, source, hashes, review, snapshotHashes) {
            const resolved = path.resolve(target);
            if (!original) original = resolved;
            let copyUnchanged = false;
            if (policy && policy.sourceSha256 === source.sha256) {
                copyUnchanged = same(policyCopyHashes, resolved === policy.readonlySnapshot.path
                    ? hashes : snapshotHashes(policy.readonlySnapshot.path));
                if (resolved === policy.readonlySnapshot.path && copyUnchanged) {
                    // A nested owner is reviewing the already pinned copy.
                    // Validate that copy and the source, without refreshing
                    // from the original midway through the outer order check.
                    const pinned = structuredClone(policy);
                    pinned.readonlySnapshot.originalDbWalShmSha256 = structuredClone(hashes);
                    return pinned;
                }
                if (resolved === original && copyUnchanged && same(policy.readonlySnapshot.originalDbWalShmSha256, hashes))
                    return structuredClone(policy);
            }
            // Changed source/copy bytes use the unchanged full owner review.
            // Its copy and race guards still decide the existing refusal.
            releaseReader();
            if (policy && !copyUnchanged) {
                checks.clear(); checkedVersion = firstReadVersion = null;
            }
            policy = chart = null;
            policyCopyHashes = null;
            policy = review();
            retainedSnapshots.add(policy.readonlySnapshot.path);
            policyCopyHashes = snapshotHashes(policy.readonlySnapshot.path);
            return structuredClone(policy);
        },
        reviewChart(source, review) {
            const key = [activePath, source.sha256];
            if (!chart || !same(chart.key, key)) chart = { key, result: review() };
            return structuredClone(chart.result);
        },
        close() {
            try { releaseReader(); }
            finally { closed = true; checks.clear(); retainedSnapshots.clear(); policy = chart = policyCopyHashes = null; }
        }
    };
    contexts.add(context);
    return context;
}

function openReadonlyDatabase(Database, target, options, startupContext) {
    if (!startupContext) return new Database(target, options);
    if (!contexts.has(startupContext)) throw new TypeError('Use an explicit startup readiness context.');
    return startupContext.open(Database, target, options);
}

module.exports = { createStartupReadinessContext, openReadonlyDatabase };

function fileHashes(target) {
    return Object.fromEntries(['', '-wal', '-shm'].map(suffix => {
        if (!fs.existsSync(target + suffix)) return [suffix, null];
        const hash = createHash('sha256'), buffer = Buffer.allocUnsafe(1024 * 1024), fd = fs.openSync(target + suffix, 'r');
        try { let length; while ((length = fs.readSync(fd, buffer, 0, buffer.length, null))) hash.update(buffer.subarray(0, length)); }
        finally { fs.closeSync(fd); }
        return [suffix, hash.digest('hex')];
    }));
}
function reviewReadonlySnapshot(target, source, startupContext) {
    startupContext?.beforeSnapshot();
    // A normal SQLite read-only open can create WAL/SHM files. Read target files
    // only, and let SQLite open an isolated, retained copy instead. Bind all
    // three originals before/after copying and classification; never retry a race.
    const before = fileHashes(target), directory = fs.mkdtempSync(path.join(os.tmpdir(), 'lims-policy-schema-readonly-'));
    const copy = path.join(directory, 'snapshot.db');
    for (const suffix of ['', '-wal', '-shm']) if (before[suffix] !== null) fs.copyFileSync(target + suffix, copy + suffix, fs.constants.COPYFILE_EXCL);
    if (JSON.stringify(fileHashes(copy)) !== JSON.stringify(before) || JSON.stringify(fileHashes(target)) !== JSON.stringify(before))
        throw fail('LAB_POLICY_SNAPSHOT_CHANGED', 'Database files changed while retaining the read-only snapshot.');
    startupContext?.useSnapshot(copy, before);
    const reader = openReadonlyDatabase(Database, copy, { readonly: true, fileMustExist: true }, startupContext); let reviewed;
    try { reviewed = reader.transaction(() => classify(reader, source))(); } finally { reader.close(); }
    if (JSON.stringify(fileHashes(target)) !== JSON.stringify(before))
        throw fail('LAB_POLICY_SNAPSHOT_CHANGED', 'Database files changed during read-only classification.');
    return { ...reviewed, readonlySnapshot: { path: copy, originalDbWalShmSha256: before, originalFilesPreserved: true } };
}

function installLabPolicySchema({ dbPath, apply = false, startupContext} = {}) {
    if (typeof dbPath !== 'string' || !dbPath.trim()) throw fail('LAB_POLICY_DATABASE_REQUIRED', 'Provide an explicit existing database path.');
    const target = path.resolve(dbPath), source = loadLabPolicyMigrationSource();
    if (!fs.existsSync(target)) throw fail('LAB_POLICY_DATABASE_REQUIRED', 'The explicit database file does not exist.');
    const reviewed = !apply && startupContext
        ? startupContext.reviewPolicy(target, source, fileHashes(target), () => reviewReadonlySnapshot(target, source, startupContext), fileHashes)
        : reviewReadonlySnapshot(target, source);
    if (reviewed.classification === 'PRESENT') return { ...reviewed, mode: 'NO_OP', totalChanges: 0, dataWrites: 0 };
    if (!apply) return { ...reviewed, mode: 'DRY_RUN', totalChanges: 0, dataWrites: 0 };
    // Revalidate the digest before opening a writer, then reclassify under its lock.
    const release = loadLabPolicyMigrationSource(), db = new Database(target, { fileMustExist: true, timeout: 5000 });
    try {
        return db.transaction(() => {
            const current = classify(db, source);
            if (current.classification === 'PRESENT') return { ...current, mode: 'NO_OP', totalChanges: 0, dataWrites: 0 };
            const before = snapshot(db);
            db.exec(current.addReportPolicyVersion ? release.sql : release.schemaSql);
            if (JSON.stringify(snapshot(db, before)) !== JSON.stringify(before) || TABLES.some(name => db.prepare('SELECT count(*) n FROM ' + quote(name)).get().n))
                throw fail('LAB_POLICY_PRESERVATION_REFUSED', 'Existing rows changed or new policy storage is populated.');
            return { ...classify(db, source), previousClassification: current.classification, mode: 'APPLIED',
                executedSql: current.plannedSql, executedDdlCount: current.plannedDdlCount, originalRowsPreserved: true,
                totalChanges: db.prepare('SELECT total_changes() n').get().n, dataWrites: 0 };
        }).immediate();
    } finally { db.close(); }
}
function assertLabPolicyStartupReady(dbPath, startupContext) {
    const result = installLabPolicySchema({ dbPath, startupContext });
    if (result.classification !== 'PRESENT') throw fail('LAB_POLICY_STARTUP_REQUIRED', 'Install the reviewed policy prerequisite before starting the lab.');
    return result;
}

function installControlCharts({dbPath,apply=false, startupContext}={}){
 if(typeof dbPath!=='string'||!dbPath.trim())throw fail('QC_CHART_DATABASE_REQUIRED','Provide an explicit database path.');
 const target=path.resolve(dbPath),source=loadControlChartMigrationSource();
 require('./install_sample_containers').assertSampleContainerStartupReady(target, apply ? undefined : startupContext);
 require('./install_lab_policy_schema').assertLabPolicyStartupReady(target, apply ? undefined : startupContext);
 const reader=openReadonlyDatabase(Database, target, {readonly:true,fileMustExist:true}, apply ? undefined : startupContext);let reviewed;
 try{reviewed=!apply&&startupContext?startupContext.reviewChart(source,()=>reader.transaction(()=>classify(reader,source))()):reader.transaction(()=>classify(reader,source))();}finally{reader.close();}
 if(!apply||reviewed.classification==='COMPLETE_214')return{...reviewed,mode:apply?'NO_OP':'DRY_RUN',totalChanges:0,backfilledCount:0};
 const db=new Database(target,{fileMustExist:true,timeout:5000});
 try{
  db.pragma('foreign_keys=ON');
  return db.transaction(()=>{
   const current=classify(db,source);
   if(current.classification==='COMPLETE_214')return{...current,mode:'NO_OP',totalChanges:0,backfilledCount:0};
   const before=snapshot(db),release=loadControlChartMigrationSource();
   db.exec(current.classification==='PRE_214'?release.sql:release.guardsSql);
   if(fingerprint(snapshot(db))!==fingerprint(before))throw fail('QC_CHART_PRESERVATION_REFUSED','Installation changed existing rows or policies.');
   const receipt={sources:current.sources,originalRowsSha256:fingerprint(before),originalRowsPreserved:true,backfilledCount:0};receipt.receiptSha256=fingerprint(receipt);
   db.prepare('INSERT INTO _schema_migrations(id,details) VALUES(?,?)').run(MARKER,JSON.stringify(receipt));
   if(db.pragma('integrity_check',{simple:true})!=='ok'||db.pragma('foreign_key_check').length)throw fail('QC_CHART_INTEGRITY_REFUSED','Installation failed integrity checks.');
   return{...classify(db,source),previousClassification:current.classification,mode:'APPLIED',backfilledCount:0,totalChanges:db.prepare('SELECT total_changes() n').get().n};
  }).immediate();
 }finally{db.close();}
}
function assertControlChartStartupReady(dbPath, startupContext){
 if(typeof dbPath!=='string'||!dbPath.trim()||!fs.existsSync(dbPath))throw fail('QC_CHART_DATABASE_REQUIRED','The lab database does not exist.');
 const result=installControlCharts({dbPath, startupContext});
 if(result.classification!=='COMPLETE_214')throw fail('QC_CHART_STARTUP_REQUIRED','Run the reviewed control chart installer before starting the lab.');
 return result;
}

function installOrderRevisions({ dbPath, apply = false, startupContext} = {}) {
    if (typeof dbPath !== 'string' || !dbPath.trim() || !fs.existsSync(dbPath)) throw fail('ORDER_REVISION_DATABASE_REQUIRED', 'Provide an existing explicit database path.');
    const target = path.resolve(dbPath), source = loadOrderRevisionMigrationSource();
    // This prerequisite's retained-copy classification never opens the original target.
    const policy = require('./install_lab_policy_schema').assertLabPolicyStartupReady(target, apply ? undefined : startupContext);
    const copy = policy.readonlySnapshot.path;
    require('./install_control_charts').assertControlChartStartupReady(copy, apply ? undefined : startupContext);
    const reader = openReadonlyDatabase(Database, copy, { readonly: true, fileMustExist: true }, apply ? undefined : startupContext); let reviewed, counts;
    try { reader.transaction(() => { reviewed = classify(reader, source); counts = impact(reader); })(); }
    finally { reader.close(); }
    if (JSON.stringify(fileHashes(target)) !== JSON.stringify(policy.readonlySnapshot.originalDbWalShmSha256)) {
        throw fail('ORDER_REVISION_SNAPSHOT_CHANGED', 'Database files changed during order classification.');
    }
    if (!apply || reviewed.classification === 'COMPLETE_209') return { ...reviewed, mode: apply ? 'NO_OP' : 'DRY_RUN', totalChanges: 0,
        backfilledCount: 0, impact: counts, readonlySnapshot: policy.readonlySnapshot };
    const release = loadOrderRevisionMigrationSource(), db = new Database(target, { fileMustExist: true, timeout: 5000 });
    // Keep the immutable DDL binding in the scanner's existing direct-call form.
    const ddl = loadOrderRevisionMigrationSource();
    try {
        db.pragma('foreign_keys=ON');
        return db.transaction(() => {
            const current = classify(db, release);
            if (current.classification === 'COMPLETE_209') return { ...current, mode: 'NO_OP', totalChanges: 0, backfilledCount: 0, impact: impact(db) };
            const before = snapshot(db);
            if (current.classification === 'PRE_209') db.exec(ddl.sql);
            else {
                const index = releaseObjects(release).find(row => row.type === 'index');
                const indexSql = 'CREATE INDEX "OrderLine_workItemId_idx" ON "OrderLine"("workItemId");';
                if (normalize(index.sql) !== normalize(indexSql)) throw fail('ORDER_REVISION_SOURCE_MISMATCH', 'Order index source differs.');
                if (!db.prepare('SELECT 1 FROM sqlite_master WHERE name=?').get(index.name)) db.exec(indexSql);
                db.exec(ddl.guardsSql);
            }
            if (hash(snapshot(db, before)) !== hash(before)) throw fail('ORDER_REVISION_PRESERVATION_REFUSED', 'Order installation changed retained rows.');
            const receipt = { sourceSha256: source.sha256, originalRowsSha256: hash(before), originalRowsPreserved: true, backfilledCount: 0 };
            receipt.receiptSha256 = hash(receipt);
            db.prepare('INSERT INTO _schema_migrations(id,details) VALUES(?,?)').run(MARKER, JSON.stringify(receipt));
            return { ...classify(db, release), previousClassification: current.classification, mode: 'APPLIED', originalRowsPreserved: true,
                backfilledCount: 0, totalChanges: db.prepare('SELECT total_changes() n').get().n, impact: impact(db) };
        }).immediate();
    } finally { db.close(); }
}

function assertOrderRevisionStartupReady(dbPath, startupContext) {
    const result = installOrderRevisions({ dbPath, startupContext });
    if (result.classification !== 'COMPLETE_209') throw fail('ORDER_REVISION_STARTUP_REQUIRED', 'Run the reviewed order-revision installer before starting the lab.');
    return result;
}

const { beginReadinessStage, readinessTelemetry } = require('./utils/startupReadinessTelemetry');
const { createStartupReadinessContext } = require('./utils/startupReadinessContext');
const startupContext = createStartupReadinessContext();

const containersReadyBegan = beginReadinessStage();
const containersReady=require('./scripts/install_sample_containers').assertSampleContainerStartupReady(dbPath, startupContext);
console.log(JSON.stringify({event:'SAMPLE_CONTAINER_STARTUP_READY',...containersReady, ...readinessTelemetry(containersReadyBegan)}));
const policyReadyBegan = beginReadinessStage();
const policyReady=require('./scripts/install_lab_policy_schema').assertLabPolicyStartupReady(dbPath, startupContext);
console.log(JSON.stringify({event:'LAB_POLICY_STARTUP_READY',...policyReady, ...readinessTelemetry(policyReadyBegan)}));
const chartsReadyBegan = beginReadinessStage();
const chartsReady=require('./scripts/install_control_charts').assertControlChartStartupReady(dbPath, startupContext);
console.log(JSON.stringify({event:'CONTROL_CHART_STARTUP_READY',...chartsReady, ...readinessTelemetry(chartsReadyBegan)}));
const orderReadyBegan = beginReadinessStage();
const orderReady=require('./scripts/install_order_revisions').assertOrderRevisionStartupReady(dbPath, startupContext);
console.log(JSON.stringify({event:'ORDER_REVISION_STARTUP_READY',...orderReady, ...readinessTelemetry(orderReadyBegan)}));

} catch (error) {
    console.error(JSON.stringify({ error: error.code || 'WORKFLOW_STARTUP_REFUSED', message: error.message,
        nextStep: error.code?.startsWith('QC_GATE_SCOPE_') ? 'Keep the lab stopped and follow docs/audit/2.4-qc-gate.md.'
            : error.code?.startsWith('CROSS_CHECK_') ? 'Keep the lab stopped and follow docs/audit/201-cross-parameter-checks.md.'
            : error.code?.startsWith('AMENDMENT_') || error.code?.startsWith('REPORT_WITHDRAWAL_') ? 'Keep the lab stopped and follow docs/audit/210-amendment-authorisation.md.'
            : error.code?.startsWith('IMPORT_') ? 'Keep the lab stopped and follow docs/audit/200-instrument-import.md.'
            : error.code?.startsWith('SAMPLE_CONTAINER_') ? 'Keep the lab stopped and follow docs/audit/206-containers-and-aliquots.md.'
            : error.code?.startsWith('ORDER_REVISION_') || error.code === 'ORDER_LINE_REQUIRED' ? 'Keep the lab stopped and follow docs/audit/209-order-revisions.md.'
            : error.code?.startsWith('QC_CHART_') || error.code?.startsWith('LAB_POLICY_') ? 'Keep the lab stopped and follow docs/audit/214-control-charts.md.'
            : error.code?.startsWith('OVERRIDE_') ? 'Keep the lab stopped and follow docs/audit/197-value-validation.md.'
            : error.code?.startsWith('CALC_') || error.code?.startsWith('CALIBRATION_') || error.code === 'UNIT_CATALOGUE_CONFLICT' ? 'Keep the lab stopped and follow docs/audit/199-calculation-templates.md.'
            : error.code?.startsWith('REAGENT_LOT_') ? 'Keep the lab stopped and follow docs/audit/194-run-first.md.'
            : error.code?.startsWith('REPORTED_VALUE_') ? 'Keep the lab stopped and follow docs/audit/192-reported-value.md.'
            : error.code?.startsWith('NCR_') ? 'Keep the lab stopped and follow docs/audit/193-nonconformity.md.'
            : error.code?.startsWith('WORK_REPEAT_') ? 'Keep the lab stopped and follow docs/audit/191-repeat-correction.md.'
            : error.code?.startsWith('WORK_ATTEMPT_') ? 'Keep the lab stopped and follow docs/audit/3.1-work-attempts.md.'
            : error.code?.startsWith('PT_') || error.code?.startsWith('RESULT_EQUIPMENT_') ? 'Keep the lab stopped and follow docs/audit/2.6-qc-audit-pt-equipment.md.'
            : error.code?.startsWith('QC_RUN_') ? 'Keep the lab stopped and follow docs/audit-2.3-normalized-qc-migration.md.'
            : error.code?.startsWith('SAMPLE_HOLD_') ? 'Keep the lab stopped and follow docs/audit/1.6-sample-holds.md.'
            : error.code?.startsWith('REFERENCE_') ? 'Keep the lab stopped and follow docs/audit/2.1-reference-materials.md.'
            : error.code?.startsWith('QC_RULE_') ? 'Keep the lab stopped and follow docs/audit/2.2-qc-rules.md.'
            : 'Keep the lab stopped and follow docs/audit/1.2-state-machine.md.', differences: error.differences || [] }));
    startupContext.close();
    process.exit(1);
} finally {
    startupContext.close();
}
